#!/usr/bin/env python3
"""Generate or freshness-check the batch scenario manifests.

Almost every workload starts from one golden template and changes exactly one
field, so each test in a batch fails only on its own workload. The exceptions
are the two CPU workloads, which start from the Guaranteed whole-CPU variant of
the template, and bad-bare-pod and bad-nodeport, which are a Pod and a Service
rather than a mutated Deployment.

The processes batch reuses the same template with a single-process command for
its golden workload, and the crds batch generates a CRD plus Roles that grant
(or over-grant) access to it.

See README.md in this directory for how to add a test to a batch.
"""

import argparse
import copy
import json
import re
import sys
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parent
ROOT = SCRIPT_DIR.parents[3]
IMAGE = "nginxinc/nginx-unprivileged:1.27"
SERVICE_ACCOUNT = "scenario-sa"
RUNTIME_CLASS = "certsuite-smoke"
# UBI ships /etc/redhat-release, which the platform check reads, and its
# curl-minimal lets the lifecycle helper drive the scale subresource.
RHEL_IMAGE = "registry.access.redhat.com/ubi9/ubi-minimal:9.5"
CRD_VERSION = "v1"
# The sample-workload image ships an sshd usable without privileges; -D keeps it
# in the foreground as a single process and -d logs to stdout.
SSHD_IMAGE = "quay.io/redhat-best-practices-for-k8s/certsuite-sample-workload"
SSHD_COMMAND = ["/usr/sbin/sshd", "-f", "/home/tnf-user/sshd/sshd_config", "-D", "-d"]
HEADER = "# Generated by batches/generate-manifests.py; do not edit by hand.\n"


# ---------------------------------------------------------------------------
# Golden template


def golden_pod_spec():
    return {
        "serviceAccountName": SERVICE_ACCOUNT,
        "securityContext": {
            "runAsNonRoot": True,
            "runAsUser": 101,
            "fsGroup": 101,
            "seLinuxOptions": {"level": "s0:c123,c456"},
        },
        "containers": [
            {
                "name": "nginx",
                "image": IMAGE,
                "imagePullPolicy": "IfNotPresent",
                "terminationMessagePolicy": "FallbackToLogsOnError",
                "resources": {"requests": {"cpu": "50m", "memory": "64Mi"}},
                "securityContext": {
                    "runAsNonRoot": True,
                    "allowPrivilegeEscalation": False,
                    "readOnlyRootFilesystem": True,
                    "capabilities": {"drop": ["ALL"]},
                },
                "lifecycle": {
                    "postStart": {"exec": {"command": ["/bin/sh", "-c", "true"]}},
                    "preStop": {"exec": {"command": ["/bin/sh", "-c", "sleep 1"]}},
                },
                "volumeMounts": [{"name": "tmp", "mountPath": "/tmp"}],
            }
        ],
        "volumes": [{"name": "tmp", "emptyDir": {}}],
    }


def container(spec):
    return spec["containers"][0]


def exec_probe(period):
    return {"exec": {"command": ["/bin/sh", "-c", "true"]}, "periodSeconds": period}


# Guaranteed QoS with whole CPUs: in scope for cpu-isolation and cpu-pinning.
CPU_PINNED_ANNOTATIONS = {
    "cpu-load-balancing.crio.io": "disable",
    "irq-load-balancing.crio.io": "disable",
}


def cpu_pinned(spec):
    container(spec)["resources"] = {
        "requests": {"cpu": "1", "memory": "128Mi"},
        "limits": {"cpu": "1", "memory": "128Mi"},
    }
    spec["runtimeClassName"] = RUNTIME_CLASS


# ---------------------------------------------------------------------------
# Object builders


def deployment(name, label, spec, replicas=1, annotations=None, extra_labels=None):
    labels = {"app": name, label: "target"}
    template_labels = dict(labels, **(extra_labels or {}))
    metadata = {"labels": template_labels}
    if annotations:
        metadata["annotations"] = annotations
    return {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {"name": name},
        "spec": {
            "replicas": replicas,
            "selector": {"matchLabels": labels},
            "template": {"metadata": metadata, "spec": spec},
        },
    }


def bare_pod(name, label, spec):
    return {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {"name": name, "labels": {"app": name, label: "target"}},
        "spec": spec,
    }


def service(name, selector_app, service_type="ClusterIP", families=("IPv4", "IPv6")):
    # ipFamilyPolicy/ipFamilies are set explicitly so the dual-stack check sees
    # a deterministic family list on the dual-stack smoke cluster.
    return {
        "apiVersion": "v1",
        "kind": "Service",
        "metadata": {"name": name},
        "spec": {
            "type": service_type,
            "selector": {"app": selector_app},
            "ports": [{"port": 8080, "targetPort": 8080, "protocol": "TCP"}],
            "ipFamilyPolicy": "PreferDualStack" if len(families) > 1 else "SingleStack",
            "ipFamilies": list(families),
        },
    }


def service_account(name=SERVICE_ACCOUNT):
    return {"apiVersion": "v1", "kind": "ServiceAccount", "metadata": {"name": name}}


def pdb(name, min_available=1):
    return {
        "apiVersion": "policy/v1",
        "kind": "PodDisruptionBudget",
        "metadata": {"name": name},
        "spec": {"minAvailable": min_available, "selector": {"matchLabels": {"app": name}}},
    }


def headless_service(name, selector_app):
    # A StatefulSet needs a governing Service. It is headless so it carries no
    # virtual IP and does not take part in the dual-stack Service checks.
    return {
        "apiVersion": "v1",
        "kind": "Service",
        "metadata": {"name": name},
        "spec": {
            "clusterIP": "None",
            "selector": {"app": selector_app},
            "ports": [{"port": 8080, "targetPort": 8080, "protocol": "TCP"}],
        },
    }


def statefulset(name, label, spec, replicas=2):
    labels = {"app": name, label: "target"}
    return {
        "apiVersion": "apps/v1",
        "kind": "StatefulSet",
        "metadata": {"name": name},
        "spec": {
            "serviceName": name,
            "replicas": replicas,
            "selector": {"matchLabels": labels},
            "template": {"metadata": {"labels": labels}, "spec": spec},
        },
    }


def runtime_class():
    return {
        "apiVersion": "node.k8s.io/v1",
        "kind": "RuntimeClass",
        "metadata": {"name": RUNTIME_CLASS},
        "handler": "runc",
    }


def resource_quota(name):
    return {
        "apiVersion": "v1",
        "kind": "ResourceQuota",
        "metadata": {"name": name},
        "spec": {"hard": {"pods": "100"}},
    }


def storage_class(name, provisioner):
    return {
        "apiVersion": "storage.k8s.io/v1",
        "kind": "StorageClass",
        "metadata": {"name": name},
        "provisioner": provisioner,
        "volumeBindingMode": "Immediate",
    }


def persistent_volume(name, storage_class_name, host_path, reclaim_policy="Delete"):
    # A statically bound hostPath volume: the matching PVC binds by storage
    # class name, capacity and access modes, so each PV gets its own class to
    # prevent cross-binding. cleanup.sh must delete these explicitly: after the
    # namespace goes away they linger in Released state and cannot rebind.
    return {
        "apiVersion": "v1",
        "kind": "PersistentVolume",
        "metadata": {"name": name},
        "spec": {
            "capacity": {"storage": "1Gi"},
            "accessModes": ["ReadWriteOnce"],
            "persistentVolumeReclaimPolicy": reclaim_policy,
            "storageClassName": storage_class_name,
            "hostPath": {"path": host_path, "type": "DirectoryOrCreate"},
        },
    }


def pvc(name, storage_class_name):
    return {
        "apiVersion": "v1",
        "kind": "PersistentVolumeClaim",
        "metadata": {"name": name},
        "spec": {
            "accessModes": ["ReadWriteOnce"],
            "storageClassName": storage_class_name,
            "resources": {"requests": {"storage": "1Gi"}},
        },
    }


def role(name, rules):
    return {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "Role",
        "metadata": {"name": name},
        "rules": rules,
    }


def cluster_role_binding(name, subject_name, subject_namespace):
    return {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "ClusterRoleBinding",
        "metadata": {"name": name},
        "subjects": [{"kind": "ServiceAccount", "name": subject_name, "namespace": subject_namespace}],
        "roleRef": {"kind": "ClusterRole", "name": "cluster-admin", "apiGroup": "rbac.authorization.k8s.io"},
    }


def role_binding(name, role_name, service_account_name):
    return {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "RoleBinding",
        "metadata": {"name": name},
        "subjects": [{"kind": "ServiceAccount", "name": service_account_name}],
        "roleRef": {"kind": "Role", "name": role_name, "apiGroup": "rbac.authorization.k8s.io"},
    }


def custom_resource_definition(plural, group, with_status, kind="ScenarioCrd", scale=False):
    if with_status and scale:
        # A status subresource would make the CR's status a separate endpoint,
        # so the scale subresource's statusReplicasPath would be unreachable
        # through the main resource.
        raise ValueError("a scale subresource needs status writes through the main resource")
    properties = {"spec": {"type": "object"}}
    if with_status or scale:
        properties["status"] = {"type": "object"}
    if scale:
        # The scale subresource reads and writes these paths. Its status must
        # stay writable through the main resource, so a CRD with a scale
        # subresource gets no status subresource.
        properties["spec"]["properties"] = {"replicas": {"type": "integer"}}
        properties["status"]["properties"] = {"replicas": {"type": "integer"}}
    version = {
        "name": CRD_VERSION,
        "served": True,
        "storage": True,
        "schema": {"openAPIV3Schema": {"type": "object", "properties": properties}},
    }
    if with_status:
        version["subresources"] = {"status": {}}
    if scale:
        version.setdefault("subresources", {})["scale"] = {
            "specReplicasPath": ".spec.replicas",
            "statusReplicasPath": ".status.replicas",
        }
    return {
        "apiVersion": "apiextensions.k8s.io/v1",
        "kind": "CustomResourceDefinition",
        "metadata": {"name": f"{plural}.{group}"},
        "spec": {
            "group": group,
            "names": {
                "plural": plural,
                "singular": plural[:-1],
                "kind": kind,
                "listKind": f"{kind}List",
            },
            "scope": "Namespaced",
            "versions": [version],
        },
    }


# ---------------------------------------------------------------------------
# pod-spec batch: one violation per workload

POD_SPEC_LABEL = "scenario-pod-spec"
# Must match NAMESPACE in pod-spec/deploy.sh: the bad-crb-binding subject names
# the namespace its service account lives in.
POD_SPEC_NAMESPACE = "pod-spec-smoke-ns"


def add_capability(cap):
    def mutate(spec):
        container(spec)["securityContext"]["capabilities"]["add"] = [cap]

    return mutate


def set_pod(key, value):
    def mutate(spec):
        spec[key] = value

    return mutate


def set_container(key, value):
    def mutate(spec):
        container(spec)[key] = value

    return mutate


def set_container_security(key, value):
    def mutate(spec):
        container(spec)["securityContext"][key] = value

    return mutate


def drop_container(key):
    def mutate(spec):
        del container(spec)[key]

    return mutate


def drop_lifecycle(hook):
    def mutate(spec):
        del container(spec)["lifecycle"][hook]

    return mutate


def drop_root_settings(spec):
    del spec["securityContext"]["runAsNonRoot"]
    del spec["securityContext"]["runAsUser"]
    del container(spec)["securityContext"]["runAsNonRoot"]


def drop_service_account(spec):
    del spec["serviceAccountName"]


def host_path_tmp(spec):
    spec["volumes"] = [{"name": "tmp", "hostPath": {"path": "/tmp", "type": "Directory"}}]


def declare_port(port):
    def mutate(spec):
        container(spec)["ports"] = [{"containerPort": port, "protocol": "TCP"}]

    return mutate


def host_port(spec):
    container(spec)["ports"] = [{"containerPort": 8080, "hostPort": 18080, "protocol": "TCP"}]


def toleration(spec):
    spec["tolerations"] = [{"key": "example.com/smoke", "operator": "Exists", "effect": "NoSchedule"}]


def no_logs(spec):
    container(spec)["command"] = ["sleep", "infinity"]


def drop_runtime_class(spec):
    del spec["runtimeClassName"]


def readiness_exec(period):
    def mutate(spec):
        container(spec)["readinessProbe"] = exec_probe(period)

    return mutate


def share_process_namespace(spec):
    spec["shareProcessNamespace"] = True


def mount_pvc(claim_name):
    def mutate(spec):
        container(spec)["volumeMounts"].append({"name": "data", "mountPath": "/data"})
        spec["volumes"].append({"name": "data", "persistentVolumeClaim": {"claimName": claim_name}})

    return mutate


# test ID -> (workload name, mutation[, base]). Base "cpu" starts from the
# Guaranteed whole-CPU variant. bad-bare-pod is a bare Pod and bad-nodeport and
# bad-ipv4 are Services, so their mutation is None.
POD_SPEC_VIOLATIONS = {
    "access-control-pod-host-network": ("bad-host-network", set_pod("hostNetwork", True)),
    "access-control-pod-host-pid": ("bad-host-pid", set_pod("hostPID", True)),
    "access-control-pod-host-ipc": ("bad-host-ipc", set_pod("hostIPC", True)),
    "access-control-pod-host-path": ("bad-host-path", host_path_tmp),
    "access-control-container-host-port": ("bad-host-port", host_port),
    "access-control-no-1337-uid": ("bad-uid-1337", lambda spec: spec["securityContext"].update(runAsUser=1337)),
    "access-control-security-context-privilege-escalation": ("bad-priv-esc", set_container_security("allowPrivilegeEscalation", True)),
    "access-control-security-context-read-only-root-file-system": ("bad-rw-root", set_container_security("readOnlyRootFilesystem", False)),
    "access-control-net-raw-capability-check": ("bad-net-raw", add_capability("NET_RAW")),
    "access-control-bpf-capability-check": ("bad-bpf", add_capability("BPF")),
    "access-control-ipc-lock-capability-check": ("bad-ipc-lock", add_capability("IPC_LOCK")),
    "access-control-net-admin-capability-check": ("bad-net-admin", add_capability("NET_ADMIN")),
    "access-control-sys-admin-capability-check": ("bad-sys-admin", add_capability("SYS_ADMIN")),
    "access-control-dac-override-capability-check": ("bad-dac-override", add_capability("DAC_OVERRIDE")),
    "access-control-dac-read-search-capability-check": ("bad-dac-read-search", add_capability("DAC_READ_SEARCH")),
    "access-control-sys-module-capability-check": ("bad-sys-module", add_capability("SYS_MODULE")),
    "access-control-requests": ("bad-no-requests", drop_container("resources")),
    "access-control-security-context-non-root-user-id-check": ("bad-root-user", drop_root_settings),
    "access-control-pod-service-account": ("bad-default-sa", drop_service_account),
    "access-control-sys-ptrace-capability": ("bad-ptrace", share_process_namespace),
    "lifecycle-image-pull-policy": ("bad-pull-always", set_container("imagePullPolicy", "Always")),
    "lifecycle-container-prestop": ("bad-no-prestop", drop_lifecycle("preStop")),
    "lifecycle-container-poststart": ("bad-no-poststart", drop_lifecycle("postStart")),
    "lifecycle-pod-owner-type": ("bad-bare-pod", None),
    "lifecycle-pod-toleration-bypass": ("bad-toleration", toleration),
    "lifecycle-pod-scheduling": ("bad-node-selector", set_pod("nodeSelector", {"kubernetes.io/os": "linux"})),
    "lifecycle-cpu-isolation": ("bad-cpu-isolation", drop_runtime_class, "cpu"),
    "observability-termination-policy": ("bad-termination-file", set_container("terminationMessagePolicy", "File")),
    "observability-container-logging": ("bad-no-logs", no_logs),
    "networking-reserved-partner-ports": ("bad-partner-port", declare_port(15000)),
    "networking-ocp-reserved-ports-usage": ("bad-ocp-port", declare_port(22623)),
    "performance-max-resources-exec-probes": ("bad-exec-probe-period", readiness_exec(5)),
    # A 10s period keeps this probe compliant for max-resources-exec-probes.
    "performance-cpu-pinning-no-exec-probes": ("bad-cpu-pinning", readiness_exec(10), "cpu"),
    "access-control-service-type": ("bad-nodeport", None),
    "access-control-cluster-role-bindings": ("bad-crb", set_pod("serviceAccountName", "bad-crb-sa")),
    "lifecycle-persistent-volume-reclaim-policy": ("bad-retain-policy", mount_pvc("bad-retain-pvc")),
    "lifecycle-storage-provisioner": ("bad-local-storage", mount_pvc("bad-storage-pvc")),
    "networking-dual-stack-service": ("bad-ipv4", None),
}

def pod_spec_workload(name, mutation, base=None):
    spec = golden_pod_spec()
    annotations = None
    if base == "cpu":
        cpu_pinned(spec)
        annotations = CPU_PINNED_ANNOTATIONS
    if mutation:
        mutation(spec)
    return deployment(name, POD_SPEC_LABEL, spec, annotations=annotations)


def pod_spec_manifests():
    golden_spec = golden_pod_spec()
    mount_pvc("good-data-pvc")(golden_spec)
    cpu_spec = golden_pod_spec()
    cpu_pinned(cpu_spec)
    golden = [
        service_account(),
        # The quota, storage class, volume and claim let the namespace,
        # resource-quota, reclaim-policy and storage-provisioner checks pass.
        resource_quota("scenario-quota"),
        storage_class("good-nfs-sc", "example.com/nfs"),
        persistent_volume("good-data-pv", "good-nfs-sc", "/tmp/scenario-good-data"),
        pvc("good-data-pvc", "good-nfs-sc"),
        deployment("golden", POD_SPEC_LABEL, golden_spec),
        deployment("good-cpu-pinned", POD_SPEC_LABEL, cpu_spec, annotations=CPU_PINNED_ANNOTATIONS),
        service("golden", "golden"),
    ]

    # bad-crb-binding makes only the bad-crb pod (running as bad-crb-sa) fail
    # the cluster role binding check. The bad-* storage objects each back one
    # violating workload: bad-storage-pv uses the not-recommended local
    # "no provisioner" class, and bad-retain-pv keeps its Retain policy.
    violations = [
        service_account(),
        service_account("bad-crb-sa"),
        cluster_role_binding("bad-crb-binding", "bad-crb-sa", POD_SPEC_NAMESPACE),
        storage_class("bad-local-storage-sc", "kubernetes.io/no-provisioner"),
        persistent_volume("bad-storage-pv", "bad-local-storage-sc", "/tmp/scenario-bad-storage"),
        pvc("bad-storage-pvc", "bad-local-storage-sc"),
        storage_class("bad-retain-sc", "example.com/nfs"),
        persistent_volume("bad-retain-pv", "bad-retain-sc", "/tmp/scenario-bad-retain", reclaim_policy="Retain"),
        pvc("bad-retain-pvc", "bad-retain-sc"),
    ]
    for name, mutation, *base in POD_SPEC_VIOLATIONS.values():
        if name == "bad-bare-pod":
            violations.append(bare_pod(name, POD_SPEC_LABEL, golden_pod_spec()))
        elif name == "bad-nodeport":
            violations.append(service(name, name, "NodePort"))
        elif name == "bad-ipv4":
            violations.append(service(name, name, families=("IPv4",)))
        else:
            violations.append(pod_spec_workload(name, mutation, *base))

    no_fs_group = golden_pod_spec()
    del no_fs_group["securityContext"]["fsGroup"]
    security_context = [service_account(), deployment("bad-security-context", POD_SPEC_LABEL, no_fs_group)]

    ptrace_spec = golden_pod_spec()
    share_process_namespace(ptrace_spec)
    container(ptrace_spec)["securityContext"]["capabilities"]["add"] = ["SYS_PTRACE"]
    ptrace = [service_account(), deployment("good-ptrace", POD_SPEC_LABEL, ptrace_spec)]

    return {
        "pod-spec/manifests/golden.yaml": golden,
        "pod-spec/manifests/violations.yaml": violations,
        "pod-spec/manifests/bad-security-context.yaml": security_context,
        "pod-spec/manifests/ptrace.yaml": ptrace,
        "pod-spec/manifests/runtimeclass.yaml": [runtime_class()],
    }


# ---------------------------------------------------------------------------
# workload-controllers batch: HA, PDB, topology spread, affinity-required

CONTROLLERS_LABEL = "scenario-controllers"


def anti_affinity(name):
    return {
        "podAntiAffinity": {
            "requiredDuringSchedulingIgnoredDuringExecution": [
                {"labelSelector": {"matchLabels": {"app": name}}, "topologyKey": "kubernetes.io/hostname"}
            ]
        }
    }


def spread(name, keys):
    return [
        {
            "maxSkew": 1,
            "topologyKey": key,
            "whenUnsatisfiable": "ScheduleAnyway",
            "labelSelector": {"matchLabels": {"app": name}},
        }
        for key in keys
    ]


def controller_spec(name, affinity="anti", tsc=None):
    spec = golden_pod_spec()
    if affinity == "anti":
        spec["affinity"] = anti_affinity(name)
    elif affinity == "node":
        spec["affinity"] = {
            "nodeAffinity": {
                "preferredDuringSchedulingIgnoredDuringExecution": [
                    {
                        "weight": 1,
                        "preference": {
                            "matchExpressions": [{"key": "kubernetes.io/os", "operator": "In", "values": ["linux"]}]
                        },
                    }
                ]
            }
        }
    if tsc:
        spec["topologySpreadConstraints"] = spread(name, tsc)
    return spec


def controller(name, replicas=2, with_pdb=True, affinity="anti", tsc=None, affinity_required=False):
    spec = controller_spec(name, affinity=affinity, tsc=tsc)
    extra = {"AffinityRequired": "true"} if affinity_required else None
    objects = [deployment(name, CONTROLLERS_LABEL, spec, replicas=replicas, extra_labels=extra)]
    if with_pdb:
        objects.append(pdb(name))
    return objects


CONTROLLER_VIOLATIONS = {
    "lifecycle-pod-high-availability": "bad-ha",
    "observability-pod-disruption-budget": "bad-pdb",
    "lifecycle-topology-spread-constraint": "bad-tsc",
    "lifecycle-affinity-required-pods": "bad-affinity-required",
}


def controller_manifests():
    golden = [service_account()]
    golden += controller("golden-ha")
    golden += controller("good-tsc", tsc=("kubernetes.io/hostname", "topology.kubernetes.io/zone"))
    golden += controller("good-affinity-required", affinity="node", affinity_required=True)
    # A StatefulSet alongside the Deployments so the two scaling checks that
    # work on each controller type have a workload to scale. It carries the same
    # HA shape as golden-ha: two replicas, anti-affinity and a PDB.
    golden += [
        headless_service("good-sts", "good-sts"),
        statefulset("good-sts", CONTROLLERS_LABEL, controller_spec("good-sts"), replicas=2),
        pdb("good-sts"),
    ]

    violations = [service_account()]
    violations += controller("bad-ha", replicas=1)
    violations += controller("bad-pdb", with_pdb=False)
    violations += controller("bad-tsc", tsc=("kubernetes.io/hostname",))
    violations += controller("bad-affinity-required", affinity_required=True)
    return {
        "workload-controllers/manifests/golden.yaml": golden,
        "workload-controllers/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# processes batch: one process per container, no SSH daemons

PROCESSES_LABEL = "scenario-processes"


def sshd_spec():
    return {
        "serviceAccountName": SERVICE_ACCOUNT,
        "containers": [
            {
                "name": "sshd",
                "image": SSHD_IMAGE,
                "imagePullPolicy": "IfNotPresent",
                "command": SSHD_COMMAND,
            }
        ],
    }


def processes_manifests():
    # "sleep infinity" is a single process; the untouched nginx template runs a
    # master plus worker processes, and sshd listens on port 2222.
    good_spec = golden_pod_spec()
    no_logs(good_spec)
    golden = [service_account(), deployment("good-single-process", PROCESSES_LABEL, good_spec)]

    violations = [
        service_account(),
        deployment("bad-multi-process", PROCESSES_LABEL, golden_pod_spec()),
        deployment("bad-sshd", PROCESSES_LABEL, sshd_spec()),
    ]
    return {
        "processes/manifests/golden.yaml": golden,
        "processes/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# crds batch: CRD-scoped RBAC and status subresource

CRDS_LABEL = "scenario-crds"
CRD_GROUP = "scenario-smoke.example.com"
CRD_PLURAL = "scenariocrds"
CRD_RULES = [{"apiGroups": [CRD_GROUP], "resources": [CRD_PLURAL], "verbs": ["get", "list", "watch"]}]


def crds_manifests():
    # No pods: both checks only look at the CRD and the Role, so the config's
    # pod label selector matches nothing. The same CRD name is used in both
    # manifests; cleanup.sh deletes it between runs.
    golden = [
        custom_resource_definition(CRD_PLURAL, CRD_GROUP, with_status=True),
        role("good-crd-role", CRD_RULES),
    ]
    violations = [
        custom_resource_definition(CRD_PLURAL, CRD_GROUP, with_status=False),
        # The extra pods rule is what makes this role fail the crd-roles check.
        role("bad-crd-role", CRD_RULES + [{"apiGroups": [""], "resources": ["pods"], "verbs": ["get", "list"]}]),
    ]
    return {
        "crds/manifests/golden.yaml": golden,
        "crds/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# platform batch: the container's distribution release


PLATFORM_LABEL = "scenario-platform"


def platform_pod(name, image, command=None):
    container = {"image": image, "imagePullPolicy": "IfNotPresent"}
    if command:
        container["command"] = command
    return bare_pod(name, PLATFORM_LABEL, {"containers": [dict(container, name="app")]})


def platform_manifests():
    # isredhat-release runs `cat /etc/redhat-release` inside every container under
    # test: a UBI image passes and an image built on another distribution fails.
    # tainted-node-kernel needs only a running workload to have nodes to judge,
    # so it rides along on the golden entry.
    golden = [platform_pod("good-rhel-release", RHEL_IMAGE, ["/bin/sh", "-c", "sleep infinity"])]
    violations = [platform_pod("bad-rhel-release", IMAGE)]
    return {
        "platform/manifests/golden.yaml": golden,
        "platform/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# lifecycle batch: pod recreation and CRD scaling

LIFECYCLE_LABEL = "scenario-lifecycle"
# Labels the helper that keeps a CR's status in step with its spec. It is
# deliberately not LIFECYCLE_LABEL: it is infrastructure, not a pod under test.
LIFECYCLE_HELPER_LABEL = "scenario-lifecycle-helper"
SCALING_GROUP = "scaling-smoke.example.com"
SCALING_PLURAL = "scenarioscalingcrs"
SCALING_KIND = "ScenarioScalingCrd"
SCALING_CR = "scaling-cr"
SCALE_SYNC_NAME = "crd-scale-sync"

# certsuite treats a scale object as ready when status.replicas equals
# spec.replicas, and the CR in this scenario has no controller, so this sidecar
# loop is the controller: read the scale subresource, mirror spec into status.
# curl-minimal ships in the UBI image the platform batch already pulls. The
# scale payload is split at "status" because the apiserver emits spec before
# status, so each half then holds exactly one replicas field.
CRD_SCALE_SYNC = """\
set -eu
SA=/var/run/secrets/kubernetes.io/serviceaccount
TOKEN="$(cat "$SA/token")"
NS="$(cat "$SA/namespace")"
URL="https://kubernetes.default.svc/apis/{group}/{version}/namespaces/$NS/{plural}/{cr}"
while :; do
  payload="$(curl -skf -H "Authorization: Bearer $TOKEN" "$URL/scale")" || true
  if [ -n "${{payload}}" ]; then
    spec="$(printf '%s' "${{payload%%\\"status\\"*}}" | sed -n 's/.*"replicas":[[:space:]]*\\([0-9]\\{{1,\\}}\\).*/\\1/p')"
    status="$(printf '%s' "${{payload#*\\"status\\"}}" | sed -n 's/.*"replicas":[[:space:]]*\\([0-9]\\{{1,\\}}\\).*/\\1/p')"
    if [ -n "$spec" ] && [ "$spec" != "${{status:-0}}" ]; then
      curl -skf -X PATCH -H "Authorization: Bearer $TOKEN" \\
        -H "Content-Type: application/merge-patch+json" \\
        -d "{{\\"status\\":{{\\"replicas\\":$spec}}}}" "$URL" >/dev/null || true
    fi
  fi
  sleep 1
done
""".format(
    group=SCALING_GROUP, version=CRD_VERSION, plural=SCALING_PLURAL, cr=SCALING_CR
)

SCALING_CRD = custom_resource_definition(
    SCALING_PLURAL, SCALING_GROUP, with_status=False, kind=SCALING_KIND, scale=True
)


def crd_scale_sync_pod():
    return bare_pod(
        SCALE_SYNC_NAME,
        LIFECYCLE_HELPER_LABEL,
        {
            "serviceAccountName": SCALE_SYNC_NAME,
            "containers": [
                {
                    "name": "sync",
                    "image": RHEL_IMAGE,
                    "imagePullPolicy": "IfNotPresent",
                    "command": ["/bin/sh", "-c", CRD_SCALE_SYNC],
                    "securityContext": {
                        "runAsNonRoot": True,
                        "runAsUser": 1001,
                        "allowPrivilegeEscalation": False,
                    },
                }
            ],
        },
    )


def lifecycle_workload(name, node_selector=None):
    spec = golden_pod_spec()
    if node_selector:
        spec["nodeSelector"] = node_selector
    # Two replicas: pod recreation cordons and drains a node, and the other
    # replica has to come back on a node that is still schedulable.
    return deployment(name, LIFECYCLE_LABEL, spec, replicas=2)


def lifecycle_manifests():
    cr = {
        "apiVersion": f"{SCALING_GROUP}/{CRD_VERSION}",
        "kind": SCALING_KIND,
        "metadata": {"name": SCALING_CR},
        "spec": {"replicas": 1},
        "status": {"replicas": 1},
    }
    # RBAC first: kubectl apply creates objects in file order, and each pod
    # cannot be admitted until its ServiceAccount exists.
    golden = [
        service_account(SCALE_SYNC_NAME),
        role(
            SCALE_SYNC_NAME,
            [
                {
                    "apiGroups": [SCALING_GROUP],
                    "resources": [SCALING_PLURAL, f"{SCALING_PLURAL}/scale"],
                    "verbs": ["get", "patch"],
                }
            ],
        ),
        role_binding(SCALE_SYNC_NAME, SCALE_SYNC_NAME, SCALE_SYNC_NAME),
        crd_scale_sync_pod(),
        cr,
        service_account(),
        lifecycle_workload("lifecycle-golden"),
    ]
    # Every Kind node matches, so the pods schedule and the deployment is
    # discovered; the nodeSelector alone is what fails the check.
    violations = [
        service_account(),
        lifecycle_workload("bad-node-selector", {"kubernetes.io/os": "linux"}),
    ]
    return {
        "lifecycle/manifests/scaling-crd.yaml": [SCALING_CRD],
        "lifecycle/manifests/golden.yaml": golden,
        "lifecycle/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# Minimal YAML emitter (stdlib only)

PLAIN = re.compile(r"^[A-Za-z_/][A-Za-z0-9_./-]*$")
AMBIGUOUS = {"true", "false", "yes", "no", "on", "off", "null", "y", "n"}


def scalar(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if PLAIN.match(value) and value.lower() not in AMBIGUOUS:
        return value
    return json.dumps(value)


def emit(value, indent=0):
    pad = " " * indent
    lines = []
    if isinstance(value, dict):
        if not value:
            return [pad + "{}"]
        for key, item in value.items():
            if isinstance(item, (dict, list)) and item:
                lines.append(f"{pad}{key}:")
                lines.extend(emit(item, indent + 2))
            elif isinstance(item, dict):
                lines.append(f"{pad}{key}: {{}}")
            elif isinstance(item, list):
                lines.append(f"{pad}{key}: []")
            else:
                lines.append(f"{pad}{key}: {scalar(item)}")
    else:
        for item in value:
            if isinstance(item, dict) and item:
                nested = emit(item, indent + 2)
                lines.append(f"{pad}- {nested[0].lstrip()}")
                lines.extend(nested[1:])
            elif isinstance(item, list) and item:
                raise ValueError("nested lists are not supported")
            else:
                lines.append(f"{pad}- {scalar(item)}")
    return lines


def render(objects):
    body = []
    for obj in objects:
        body.append("---")
        body.extend(emit(obj))
    return HEADER + "\n".join(body) + "\n"


def all_manifests():
    manifests = {}
    manifests.update(pod_spec_manifests())
    manifests.update(controller_manifests())
    manifests.update(processes_manifests())
    manifests.update(crds_manifests())
    manifests.update(platform_manifests())
    manifests.update(lifecycle_manifests())
    return {path: render(objects) for path, objects in manifests.items()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if a generated manifest is stale")
    args = parser.parse_args()

    stale = []
    for relative, content in all_manifests().items():
        path = SCRIPT_DIR / relative
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                stale.append(str(path.relative_to(ROOT)))
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"Wrote {path.relative_to(ROOT)}")

    if stale:
        print("Batch manifests are stale. Run python3 .github/actions/test-scenarios/batches/generate-manifests.py:", file=sys.stderr)
        for path in stale:
            print(f"  {path}", file=sys.stderr)
        return 1
    if args.check:
        print("Batch manifests are up to date.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
